import { test } from '@playwright/test';
import { DOCS, PARENT_B, expectDocOpen } from './legal-docs.helpers';

test.use({ storageState: PARENT_B });

test.describe('Юридические документы — родитель под входом', () => {
  test('Политика конфиденциальности открывается под входом и переживает перезагрузку @desktop @prod-safe #d7fe2c', async ({ page }) => {
    await page.goto(DOCS.privacy.url);
    await expectDocOpen(page, 'privacy');

    await page.reload();
    await expectDocOpen(page, 'privacy');
  });
});
